def one(k, v, h, km, vm, form):
    from scipy.sparse import diags
    d = (k[:-1] + k[1:]) / 2 if km == 0 else 2 * k[:-1] * k[1:] / (k[:-1] + k[1:])
    d = d / h ** 2
    if vm == 0:
        f = (v[:-1] + v[1:]) / 2 / h
        p = np.maximum(f, 0)
        m = np.maximum(-f, 0)
    elif vm == 1:
        p = np.maximum(v[:-1], 0) / h
        m = np.maximum(-v[1:], 0) / h
    else:
        p = np.maximum(v[1:], 0) / h
        m = np.maximum(-v[:-1], 0) / h
    if form == 0:
        a = np.r_[d + p, 0] + np.r_[0, d + m]
    else:
        a = np.r_[d + m, 0] + np.r_[0, d + p]
    return diags([-d - p, a, -d - m], [-1, 0, 1], format='csc')
